'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const path = require('node:path');

const SCRIPT = path.join(__dirname, '..', 'slug.js');
const USAGE = 'Usage: node slug.js "<title>"';

function run(...args) {
  const result = spawnSync(process.execPath, [SCRIPT, ...args], { encoding: 'utf8' });
  return { stdout: result.stdout, stderr: result.stderr, code: result.status };
}

function assertSlug(args, expected) {
  const { stdout, stderr, code } = run(...args);
  assert.equal(stdout, `${expected}\n`);
  assert.equal(stderr, '');
  assert.equal(code, 0);
}

function assertUsageError(args) {
  const { stdout, stderr, code } = run(...args);
  assert.equal(stdout, '');
  assert.equal(stderr, `${USAGE}\n`);
  assert.equal(code, 1);
}

test('R-01: prints the slug of the title', () => {
  assertSlug(['Hello World'], 'hello-world');
});

test('R-02: collapses spaces and punctuation and trims dashes', () => {
  assertSlug(['  Hello,  World!! '], 'hello-world');
});

test('R-02: turns accented letters into plain letters', () => {
  assertSlug(['Café Déjà Vu'], 'cafe-deja-vu');
});

test('R-02: turns letters with strokes and ligatures into plain letters', () => {
  assertSlug(['Straße Søren'], 'strasse-soren');
  assertSlug(['Łódź Đak Æsir Œuvre'], 'lodz-dak-aesir-oeuvre');
  assertSlug(['Ħamrun Ŧ Ƀ Ƶ'], 'hamrun-t-b-z');
});

test('R-03: no title is a usage error', () => {
  assertUsageError([]);
});

test('R-03: an empty title is a usage error', () => {
  assertUsageError(['']);
});

test('R-03: a title with nothing left is a usage error', () => {
  assertUsageError(['!!!']);
});

test('R-04: several words without quotes are one title', () => {
  assertSlug(['Hello', 'World'], 'hello-world');
});

test('R-04: --help and -h print the usage message', () => {
  for (const flag of ['--help', '-h']) {
    const { stdout, stderr, code } = run(flag);
    assert.equal(stdout, `${USAGE}\n`);
    assert.equal(stderr, '');
    assert.equal(code, 0);
  }
});

test('R-04: any other argument starting with a dash is title text', () => {
  assertSlug(['-x'], 'x');
});

test('R-05: keeps digits, drops apostrophes, treats underscores as punctuation', () => {
  assertSlug(["Don't Stop 2 Believe_Now"], 'dont-stop-2-believe-now');
});

test('R-05: drops curly apostrophes and emoji', () => {
  assertSlug(['It’s 🎉 Time'], 'its-time');
});

test('R-05: a title of only non-Latin letters is a usage error', () => {
  assertUsageError(['日本語']);
});

